WebServer server(80);

// =====================================================
// LED STATE
// =====================================================

uint8_t currentR = 128;
uint8_t currentG = 0;
uint8_t currentB = 255;

uint8_t brightness = 150;
bool lightsOn = true;

// =====================================================
// LED FUNCTIONS
// =====================================================

void showCurrentColor() {

  if (!lightsOn) {
    strip.clear();
    strip.show();
    return;
  }

  for (int i = 0; i < LED_COUNT; i++) {
    strip.setPixelColor(
      i,
      strip.Color(currentR, currentG, currentB)
    );
  }

  strip.show();
}

void setColor(uint8_t r, uint8_t g, uint8_t b) {

  currentR = r;
  currentG = g;
  currentB = b;

  lightsOn = true;

  showCurrentColor();
}

// =====================================================
// INA226 SCANNER
// =====================================================

void scanINA226() {

  inaFound = false;
  inaAddress = 0;

  Serial.println();
  Serial.println("Scanning I2C bus...");

  for (byte address = 1; address < 127; address++) {

    Wire.beginTransmission(address);
    byte error = Wire.endTransmission();

    if (error == 0) {

      Serial.print("I2C DEVICE FOUND: 0x");

      if (address < 16) {
        Serial.print("0");
      }

      Serial.println(address, HEX);

      // INA226 commonly defaults to 0x40
      if (address >= 0x40 && address <= 0x4F) {
        inaFound = true;
        inaAddress = address;
      }
    }
  }

  if (inaFound) {

    Serial.print("INA226 FOUND AT 0x");
    Serial.println(inaAddress, HEX);

  } else {

    Serial.println("INA226 NOT FOUND");
  }
}

